        "correctAnswer": -1,
        "explanation": "भारतीय गन्ना अनुसंधान संस्थान\n–\nलखनऊ में\nराष्ट्रीय पौध सुरक्षा प्रिशक्षण संस्थान\n–\nहैदराबाद में\nनई िदल्ली के पूसा पिरसर में राष्ट्रीय पादप आनुवंिशक संसाधन ब्यूरो\n(National Bureau of Plant Genetic Resources) है न िक राष्ट्रीय\nपादप आनुवंिशक अनुसंधान (Research) ब्यूरो। जनवरी‚ 1977 से ‘राष्ट्रीय\nपादप पिरचय ब्यूरो’ को ही राष्ट्रीय पादप आनुवंिशक संसाधन ब्यूरो कहा जाने\nलगा। वषर् 1966 में केंद्रीय पौध संरक्षण प्रिशक्षण संस्थान (Central Plant\nProtection Institute) की स्थापना हैदराबाद में की गई थी। बाद में इसे\nराष्ट्रीय पौध संरक्षण प्रिशक्षण संस्थान के रूप में जाना जाने लगा। 24 अक्टूबर‚\n2008 को संस्थान को एक स्वायत्त िनकाय ‘राष्ट्रीय वनस्पित स्वास्थ्य प्रबंधन\nसंस्थान’ (National Institute of Plant Health Management) के रूप\nमें पंजीकृत िकया गया। गेहूं अनुसंधान िनदेशालय करनाल में है‚ िजसे वतर्मान\nमें भारतीय गेहूं एवं जौ अनुसंधान संस्थान के रूप में जाना जाता है। ध्यातव्य\nहै िक राष्ट्रीय वनस्पित स्वास्थ्य प्रबंधन संस्थान कृिष एवं िकसान कल्याण\nमंत्रालय (भारत सरकार) के कृिष एवं िकसान कल्याण िवभाग के अंतगर्त है।\nअत: िदए गए प्रश्न में िकसी भी िवकल्प का सही चयन करना संभव नहीं है।"
